css:
.fx-rv{width:min(1000px,100%);display:grid;gap:5em;padding:2em 0 14vh}
.fx-rv .hint{opacity:.5;font-size:.85em;text-align:center}
.fx-rv h2{font-size:clamp(2em,5vw,3.4em);max-width:16ch}
.fx-rv .row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.4em}
.fx-rv .item{padding:1.5em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-rv .item b{display:block;font:600 1.3em var(--font-heading);margin-bottom:.3em}.fx-rv .item span{opacity:.68;font-size:.95em}
.fx-rv [data-rv]{opacity:0;transform:translateY(28px);transition:opacity calc(.8s/var(--speed)) ease,transform calc(.8s/var(--speed)) cubic-bezier(.2,.8,.2,1);transition-delay:calc(var(--d,0)*110ms/var(--speed))}
.fx-rv [data-rv].in{opacity:1;transform:none}
@media(max-width:760px){.fx-rv .row{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.fx-rv [data-rv]{opacity:1;transform:none;transition:none}}
